using System;
using System.IO;
using System.Reflection;
using System.Collections.Generic;
namespace Downfield {
public static class RosterEconomyFixTests {
 static int checks,failures;static void Check(bool ok,string name){checks++;if(!ok){failures++;Console.WriteLine("FAIL Roster/economy fixes: "+name);}}
 static Franchise New(){return Franchise.Create(new Profile(),new Roster());}
 public static int Run(){checks=failures=0;string old=Profile.StorageOverride,folder=Path.Combine(Path.GetTempPath(),"Downfield-rebalance-"+Guid.NewGuid().ToString("N"));Profile.StorageOverride=Path.Combine(folder,"club.txt");try{
  Franchise f=New();foreach(LeagueTeam t in f.Teams){Check(f.Payroll(t.Id)<=Franchise.Cap-30,"initial cap room for replacements / "+t.Id);Check(f.ProjectedIncome(t.Id,false)>f.OperatingCosts(t.Id,false),"away game pays routine costs / "+t.Id);}
  f.EconomyVersion=0;f.Credits=-99;f.Season=3;f.Coach.Wins=25;int player=f.Starter(f.UserTeam,0).Id;foreach(ClubPlayer p in f.Players){p.Salary=22;p.InjuryWeeks=6;}foreach(LeagueTeam t in f.Teams)f.BusinessFor(t.Id).Cash=-80;f.Save();f=Franchise.Load(new Profile(),new Roster());Check(f.Credits==40&&f.Season==3&&f.Coach.Wins==25&&f.Starter(f.UserTeam,0).Id==player,"old negative save repaired without resetting career or roster");foreach(LeagueTeam t in f.Teams)Check(f.BusinessFor(t.Id).Cash>=40&&f.Payroll(t.Id)<=Franchise.Cap-12,"all clubs repaired / "+t.Id);Check(f.Players.TrueForAll(p=>p.InjuryWeeks<=2),"legacy injury backlog shortened");f.Credits=7;f.Save();f=Franchise.Load(new Profile(),new Roster());Check(f.Credits==7&&f.EconomyVersion==1,"migration never repeatedly grants free money");
  f=New();ClubPlayer starter=f.Starter(f.UserTeam,1),reserve=f.Squad(f.UserTeam).Find(p=>p.Role=="RB"&&p.Slot<0);Simulation s=new Simulation(120);f.Apply(s,1);s.NewGame();int original=s.Players[1].ClubId;int priorDefense=s.Defense;f.Starter(f.UserTeam,11).OVR=99;s.DepthPersonnelPending=true;f.StartPlayer(reserve.Id,1);Check(s.Players[1].ClubId==original,"depth edit leaves current personnel intact until refresh");s.RefreshDepthPersonnel();Check(s.Players[1].ClubId==reserve.Id,"presnap edit dresses chosen starter");Check(s.Defense==f.Defense+f.Club.CoachDef+(f.Rating(f.UserTeam,true)-75)/4&&s.Defense>=priorDefense,"defensive chart changes update simulated defensive strength");s.Snap();f.StartPlayer(starter.Id,1);s.DepthPersonnelPending=true;float spot=s.Spot;s.RefreshDepthPersonnel();Check(s.State==Phase.Live&&s.Players[1].ClubId==reserve.Id&&s.Spot==spot,"live substitution cannot reset or teleport the current play");s.State=Phase.Dead;s.Next();Check(s.Players[1].ClubId==starter.Id,"queued lineup arrives at next play");starter.InjuryWeeks=2;f.StartPlayer(starter.Id,1);f.StartPlayer(reserve.Id,1);f.StartPlayer(starter.Id,1);Check(f.Starter(f.UserTeam,1).Id==reserve.Id,"injured starter cannot be selected into active lineup");
  int injuries=0;MethodInfo tryInjury=typeof(Simulation).GetMethod("TryInjury",BindingFlags.Instance|BindingFlags.NonPublic);for(int seed=0;seed<1000;seed++){s=new Simulation(seed);s.Difficulty=4;Player p=s.Players[0];p.ClubId=1;for(int hit=0;hit<50;hit++)tryInjury.Invoke(s,new object[]{p,false});injuries+=s.MatchInjuries.Count;Check(s.InjuryReports.TrueForAll(r=>r.Weeks<=2),"ordinary injuries recover in at most two weeks / "+seed);}Check(injuries>=10&&injuries<=45,"50 repeated hard-mode hits get one medical roll per player: "+injuries+" / 1000");Check(Simulation.SeriousInjuryChance(true,3)<Simulation.SeriousInjuryChance(true,0),"fitness lowers injury risk");
  f=New();bool solvent=true;int minimumCash=999,maximumPayroll=0;for(int year=0;year<6;year++){while(!f.Complete){if(f.UserGame!=null)f.FinishGame(f.UserGame.Id,28,14);else f.Advance();foreach(LeagueTeam t in f.Teams){int cash=t.Id==f.UserTeam?f.Credits:f.BusinessFor(t.Id).Cash;minimumCash=Math.Min(minimumCash,cash);maximumPayroll=Math.Max(maximumPayroll,f.Payroll(t.Id));solvent&=cash>=0&&f.Payroll(t.Id)<=Franchise.Cap&&f.Squad(t.Id).Count<=Franchise.MaxRoster;}}if(year<5){f.NextSeason();f.AutoDraft();solvent&=!f.DraftActive;}}
  Console.WriteLine("Rebalanced league / six seasons / lowest cash $"+minimumCash+" / highest payroll $"+maximumPayroll);Check(solvent,"six seasons: every club solvent, legal cap, complete drafts and roster limits");
  Console.WriteLine("Roster/economy fixes: "+checks+" checks, "+failures+" failures");return failures;
 }finally{Profile.StorageOverride=old;if(Directory.Exists(folder))Directory.Delete(folder,true);}}
}
}
